    output$sets <- renderUI({
      owned <- player$rv$album; claimed <- player$rv$sets_claimed
      div(class = "album-sets", lapply(seq_len(nrow(ALBUM_SETS)), function(s) {
        cards <- ALBUM_CARDS[ALBUM_CARDS$set == s, ]
