                  div(class = "ac-name", if (n > 0) tr(cd$name) else "???"),
                  div(class = "ac-stars", strrep("\u2605", cd$stars)),
                  if (n > 1) span(class = "ac-count", paste0("x", n)))
            })))
      }))
