}

html, body { background: var(--fc-bg); }
body { color: var(--fc-text); background: var(--fc-bg) !important; min-height: 100vh; }
/* fixed, composited background layers (no repaint on scroll) */
body::after {
  content: ""; position: fixed; inset: 0; pointer-events: none; z-index: -1;
  background:
    radial-gradient(1200px 600px at 10% -10%, rgba(123, 44, 191, .45), transparent 60%),
    radial-gradient(900px 500px at 110% 10%, rgba(255, 46, 136, .25), transparent 60%),
    radial-gradient(800px 600px at 50% 120%, rgba(0, 194, 255, .12), transparent 60%);
}
body::before {
  content: ""; position: fixed; inset: 0; pointer-events: none; z-index: 0; opacity: .35;
  background-image: radial-gradient(rgba(255,255,255,.55) 1px, transparent 1.4px);
  background-size: 46px 46px;
  mask-image: linear-gradient(180deg, #000 0%, transparent 70%);
}
/* the navbar (and its dropdown menus) must stack above the page content */
.container-fluid { position: relative; z-index: 1; }
