.sm-title { display: flex; align-items: center; gap: .8rem; }
.sm-art { font-size: 2.8rem; filter: drop-shadow(0 0 14px var(--glow)); }
.sm-title h3 { margin: 0; font-size: 1.55rem; background: var(--gold-grad); -webkit-background-clip: text; background-clip: text; color: transparent; filter: drop-shadow(0 2px 0 rgba(0,0,0,.5)); }
.sm-title p { margin: 0; color: rgba(255,255,255,.8); font-size: .85rem; }
.sm-badges { display: flex; align-items: center; gap: .4rem; }
.badge-vol, .badge-rtp { font-size: .7rem; font-weight: 800; padding: .25rem .65rem; border-radius: 99px; background: rgba(0,0,0,.4); border: 1px solid rgba(255,255,255,.2); }
.badge-rtp { color: var(--fc-green); }
.btn-info-round { width: 2rem; height: 2rem; border-radius: 50%; border: 2px solid var(--fc-gold); background: rgba(0,0,0,.45); color: var(--fc-gold); font-weight: 900; font-family: Georgia, serif; cursor: pointer; }
.popover { max-width: 520px; --bs-popover-bg: #1d0838; --bs-popover-border-color: rgba(255,204,0,.4); --bs-popover-header-bg: #2c0d52; --bs-popover-body-color: #eadcff; --bs-popover-header-color: #ffd23f; }
.pt-desc { font-size: .82rem; color: #dccbff; }
.paytable { width: 100%; font-size: .8rem; border-collapse: collapse; }
.paytable td { padding: .22rem .35rem; border-bottom: 1px solid rgba(255,255,255,.08); }
.pt-sym { font-size: 1.3rem; width: 2.2rem; text-align: center; }
.pt-sym .bar { display: block; font-size: .45rem; }
.pt-pays span { color: var(--fc-gold); font-weight: 800; }
.pt-note { font-size: .72rem; color: var(--fc-muted); margin: .5rem 0 0; }

.meters { display: flex; flex-wrap: wrap; gap: .5rem; margin: .7rem 0 .2rem; }
.meter { flex: 1 1 260px; display: grid; grid-template-columns: auto 1fr auto; align-items: center; gap: .6rem; background: rgba(0,0,0,.35); border-radius: 99px; padding: .3rem .8rem; border: 1px solid rgba(255,255,255,.12); }
.meter-label { font-size: .66rem; font-weight: 900; letter-spacing: 1.5px; color: #ffe8a3; }
.meter-bar { height: 10px; background: rgba(255,255,255,.12); border-radius: 99px; overflow: hidden; }
.meter-fill { height: 100%; background: linear-gradient(90deg, var(--fc-cyan), #9ef7ff); border-radius: 99px; transition: width .6s ease; }
.meter.heat .meter-fill { background: linear-gradient(90deg, #ffb400, #ff3d00); box-shadow: 0 0 10px #ff6a00; }
.meter.pearls .meter-fill { background: linear-gradient(90deg, #e6f7ff, #ffffff); box-shadow: 0 0 10px #bff; }
.meter.clock .meter-fill { background: linear-gradient(90deg, #8aa4ff, #ffd23f); }
.meter.freespins { border-color: var(--fc-gold); box-shadow: 0 0 14px rgba(255,204,0,.4); }
.meter.freespins .meter-fill { background: var(--gold-grad); }
.meter.map .meter-fill { background: linear-gradient(90deg, #00c2ff, #ffd23f); }
.meter.climb .meter-fill { background: linear-gradient(90deg, #3ddc84, #b6ff6e); }
.meter.boost { flex: 0 1 auto; }
.meter-text { font-size: .78rem; font-weight: 800; white-space: nowrap; font-variant-numeric: tabular-nums; }
.jp-pill { flex: 1 1 120px; }

.reels-wrap { position: relative; margin-top: .6rem; }
.reels-frame { border-radius: 1.2rem; padding: .7rem; background: linear-gradient(180deg, #000 0%, rgba(0,0,0,.75) 100%); box-shadow: inset 0 0 30px rgba(0,0,0,.9), 0 0 0 2px rgba(212, 175, 55, .7); }
.reels { display: grid; grid-template-columns: repeat(var(--reels), 1fr); gap: .55rem; }
.reel { display: grid; grid-template-rows: repeat(var(--rows), 1fr); gap: .55rem; border-radius: .9rem; padding: .1rem; position: relative; }
/* spinning: real cells hidden, a pre-rendered strip scrolls (transform only) */
.reel { overflow: hidden; }
.reel.spinning > .cell { visibility: hidden; }
.reel-strip { position: absolute; left: .1rem; right: .1rem; top: 0; display: flex; flex-direction: column; gap: .55rem; will-change: transform; animation: stripScroll .22s linear infinite; opacity: .9; }
body.turbo .reel-strip { animation-duration: .12s; }
.strip-cell { flex: 0 0 auto; height: clamp(64px, 14.5vh, 138px); border-radius: .85rem; display: flex; align-items: center; justify-content: center; background: rgba(255,255,255,.06); }
.slot-machine.rows-4 .strip-cell { height: clamp(54px, 11vh, 108px); }
.slot-machine.dual .strip-cell { height: clamp(58px, 12vh, 118px); }
.strip-cell .sym { filter: none; opacity: .85; }
.strip-cell.royal .sym { font-family: var(--display); color: #cfd8ff; }
@keyframes stripScroll { from { transform: translateY(-50%); } to { transform: translateY(0); } }
.reel.spinning::after { content: ""; position: absolute; inset: 0; pointer-events: none; background: linear-gradient(180deg, rgba(0,0,0,.55), transparent 25%, transparent 75%, rgba(0,0,0,.55)); }
.cell.shimmer .sym { animation: shimmer .16s linear infinite; }
@keyframes shimmer { 0% { transform: translateY(-8%); opacity: .55; } 100% { transform: translateY(8%); opacity: .55; } }
.cell {
  position: relative; height: clamp(64px, 14.5vh, 138px); border-radius: .85rem; display: flex; align-items: center; justify-content: center; overflow: hidden;
  background: radial-gradient(circle at 50% 30%, rgba(255,255,255,.2), rgba(255,255,255,.04) 55%, rgba(0,0,0,.25)), linear-gradient(180deg, rgba(255,255,255,.07), rgba(0,0,0,.25));
  box-shadow: inset 0 2px 0 rgba(255,255,255,.12), inset 0 -3px 8px rgba(0,0,0,.45);
  transition: opacity .25s, filter .25s, transform .2s;
}
.slot-machine.rows-4 .cell { height: clamp(54px, 11vh, 108px); }
.slot-machine.reels-3 { max-width: 760px; }
.slot-machine.dual .cell { height: clamp(58px, 12vh, 118px); }
.sym { font-size: clamp(1.8rem, min(5vw, 8.5vh), 3.8rem); line-height: 1; filter: drop-shadow(0 6px 6px rgba(0,0,0,.55)); user-select: none; }
.slot-machine.rows-4 .sym { font-size: clamp(1.6rem, min(4.4vw, 7vh), 3.2rem); }
.slot-machine.reels-3 .sym { font-size: clamp(2.2rem, min(7vw, 9vh), 4.4rem); }
.cell.royal .sym { font-family: var(--display); font-size: clamp(1.6rem, 4.4vw, 3.2rem); background: linear-gradient(180deg, #fff, #b8c6ff); -webkit-background-clip: text; background-clip: text; color: transparent; }
.cell.seven .sym { font-family: var(--display); font-size: clamp(2.4rem, 7vw, 5rem); -webkit-text-stroke: 2px #fff3; }
.cell.seven-red .sym { background: linear-gradient(180deg, #ff8a8a, #e0002a 60%, #8a0018); -webkit-background-clip: text; background-clip: text; color: transparent; }
.cell.seven-blue .sym { background: linear-gradient(180deg, #9ad7ff, #0077ff 60%, #003c8a); -webkit-background-clip: text; background-clip: text; color: transparent; }
.cell.bars .sym, .pt-sym.bars { display: flex; flex-direction: column; gap: 3px; }
.bar { display: block; font-family: var(--display); font-size: clamp(.55rem, 1.6vw, 1rem); line-height: 1; padding: .14em .5em; border-radius: .3em; background: #111; color: #ffd23f; border: 2px solid #ffd23f; font-weight: 400; }
.cell.blank .sym { opacity: 0; }
.cell.wild { background: radial-gradient(circle at 50% 35%, rgba(255,230,120,.5), rgba(255,160,0,.18) 55%, rgba(0,0,0,.3)); box-shadow: inset 0 0 0 2px rgba(255, 204, 0, .8), inset 0 0 18px rgba(255,204,0,.35); }
.cell.wild::after { content: "WILD"; position: absolute; bottom: 4%; left: 50%; transform: translateX(-50%); font-family: var(--display); font-size: clamp(.45rem, 1.1vw, .72rem); color: #2a1300; background: var(--gold-grad); padding: .05rem .45rem; border-radius: 99px; letter-spacing: 1px; box-shadow: 0 2px 6px rgba(0,0,0,.5); }
.cell.scatter { box-shadow: inset 0 0 0 2px rgba(0, 194, 255, .7), inset 0 0 18px rgba(0,194,255,.3); }
.cell.collect { box-shadow: inset 0 0 0 2px rgba(160, 255, 200, .6); }
.cell.mystery { background: linear-gradient(160deg, #4d2a8a, #1b0b3b); }
.cell.mystery .sym { font-family: var(--display); color: #ffd23f; }
.cell.ruby .sym { filter: hue-rotate(140deg) saturate(2.2) drop-shadow(0 0 10px rgba(255,0,70,.7)); }
.cell.blood-moon .sym { filter: sepia(1) saturate(6) hue-rotate(-40deg) drop-shadow(0 0 12px #f00); }
.cell.phoenix .sym { filter: sepia(.6) saturate(3) hue-rotate(-20deg) drop-shadow(0 0 10px #ff6a00); }
.cell.carriage { box-shadow: inset 0 0 0 2px #a8c4ff, inset 0 0 20px rgba(168,196,255,.5); }
.cell-badge:empty { display: none; }
.cell-badge { position: absolute; top: 5%; right: 6%; font-weight: 900; font-size: clamp(.6rem, 1.3vw, .85rem); padding: .05rem .4rem; border-radius: 99px; background: var(--pink-grad); color: #fff; box-shadow: 0 2px 6px rgba(0,0,0,.5); }
.cell.fireball .cell-badge, .cell.held .cell-badge { background: var(--gold-grad); color: #2a1300; font-size: clamp(.7rem, 1.6vw, 1rem); top: auto; bottom: 6%; right: 50%; transform: translateX(50%); }

.cell.land { animation: land .32s cubic-bezier(.3, 1.6, .5, 1); }
@keyframes land { 0% { transform: translateY(-18%); } 100% { transform: translateY(0); } }
.cell.win { animation: winPulse 1s ease-in-out infinite; z-index: 2; box-shadow: 0 0 0 3px var(--fc-gold), 0 0 24px rgba(255, 204, 0, .85), inset 0 0 20px rgba(255, 230, 120, .45); }
@keyframes winPulse { 0%, 100% { transform: scale(1); } 50% { transform: scale(1.06); } }
.cell.dim { opacity: .38; filter: grayscale(.5); }
.cell.explode { animation: explode .36s ease-in forwards; }
@keyframes explode { to { transform: scale(1.5) rotate(12deg); opacity: 0; filter: brightness(3); } }
.cell.dropped { animation: drop .38s cubic-bezier(.3, 1.4, .5, 1); }
@keyframes drop { 0% { transform: translateY(-120%); opacity: 0; } 100% { transform: none; opacity: 1; } }
.cell.expanded, .cell.grow, .cell.dragon-reel, .cell.transform, .cell.reveal, .cell.revived, .cell.transfer { animation: morph .45s ease; }
@keyframes morph { 0% { transform: scale(.4) rotateY(90deg); filter: brightness(3); } 100% { transform: none; } }
.cell.expanded, .cell.dragon-reel { box-shadow: inset 0 0 0 3px #ffd23f, 0 0 20px rgba(255,120,0,.7); }
.cell.dragon-reel { background: radial-gradient(circle, rgba(255,90,0,.55), rgba(120,0,0,.5)); }
.cell.grow { background: radial-gradient(circle, rgba(120,255,80,.35), rgba(20,80,10,.4)); }
.cell.stone .sym { filter: grayscale(1) brightness(1.35) contrast(.9) drop-shadow(0 0 6px #cfe9c2); }
.cell.stone { background: linear-gradient(160deg, #6d7468, #2e332b); box-shadow: inset 0 0 0 2px #a9c79c; }
.cell.sticky { box-shadow: inset 0 0 0 3px #ff4fb0, 0 0 16px rgba(255, 79, 176, .7); }
.cell.held { box-shadow: inset 0 0 0 3px var(--fc-gold), 0 0 14px rgba(255, 204, 0, .6); }
.cell.new-held { animation: morph .45s ease; }
.cell.nudged { animation: nudge .45s ease; }
@keyframes nudge { 0% { transform: translateY(-35%); } 60% { transform: translateY(6%); } 100% { transform: none; } }
.cell.transfer { box-shadow: inset 0 0 0 3px #ff1744, 0 0 18px rgba(255, 23, 68, .8); }

.reel-note { position: absolute; left: 50%; top: -.6rem; transform: translate(-50%, -40%); z-index: 5; pointer-events: none; opacity: 0; font-family: var(--display); font-size: .95rem; color: #fff; padding: .3rem 1rem; border-radius: 99px; background: var(--pink-grad); box-shadow: 0 6px 20px rgba(0,0,0,.5); white-space: nowrap; }
.reel-note.show { animation: noteIn 2.4s ease forwards; }
@keyframes noteIn { 0% { opacity: 0; transform: translate(-50%, -10%) scale(.8); } 12% { opacity: 1; transform: translate(-50%, -40%) scale(1.05); } 80% { opacity: 1; } 100% { opacity: 0; } }
.win-banner { position: absolute; inset: 0; display: flex; align-items: center; justify-content: center; pointer-events: none; z-index: 6; opacity: 0; }
.win-banner.show { opacity: 1; animation: bannerIn .35s cubic-bezier(.3, 1.6, .5, 1); }
.win-banner { font-family: var(--display); font-size: clamp(1.6rem, 5vw, 3.2rem); color: #fff; text-shadow: 0 4px 0 #7a004a, 0 0 30px rgba(255, 46, 136, .9); }
.win-banner b { background: var(--gold-grad); -webkit-background-clip: text; background-clip: text; color: transparent; font-weight: 400; text-shadow: none; filter: drop-shadow(0 4px 0 #7a3b00); margin-left: .3em; }
.win-banner.small { font-size: clamp(1.2rem, 3.4vw, 2.2rem); }
@keyframes bannerIn { 0% { transform: scale(.3); } 100% { transform: scale(1); } }

.sm-controls { display: grid; grid-template-columns: 1.3fr 1fr 1.2fr; gap: .8rem; align-items: center; margin-top: .9rem; }
.ctl-group { display: flex; flex-direction: column; align-items: center; gap: .25rem; background: rgba(0,0,0,.35); border-radius: 1rem; padding: .5rem .7rem; border: 1px solid rgba(255,255,255,.1); }
.bet-group { flex-direction: row; flex-wrap: wrap; justify-content: center; gap: .45rem; }
.bet-group .ctl-label { width: 100%; text-align: center; }
.bet-stepper { display: flex; align-items: center; gap: .35rem; }
.btn-step { width: 2.3rem; height: 2.3rem; border-radius: 50%; border: none; font-size: 1.3rem; font-weight: 900; line-height: 1; background: linear-gradient(180deg, #6d35b8, #3b1670); color: #fff; box-shadow: 0 3px 0 #220a45; padding: 0; }
.btn-step:hover { filter: brightness(1.2); color: #fff; }
.bet-val { min-width: 6.5rem; text-align: center; font-family: var(--display); font-size: 1.2rem; color: var(--fc-gold); }
.btn-maxbet { border: none; border-radius: 99px; padding: .4rem .9rem; font-weight: 900; font-size: .75rem; background: var(--gold-grad); color: #2a1300; box-shadow: 0 3px 0 #a35f00; }
.win-val { font-family: var(--display); font-size: 1.7rem; background: var(--gold-grad); -webkit-background-clip: text; background-clip: text; color: transparent; font-variant-numeric: tabular-nums; }
.spin-group { flex-direction: row; justify-content: center; gap: .7rem; }
.btn-spin {
  width: 6.4rem; height: 6.4rem; border-radius: 50%; border: 4px solid #ffe38a; padding: 0; font-family: var(--display); font-size: 1.35rem; color: #fff;
  background: radial-gradient(circle at 50% 30%, #7dffb2, #16c172 45%, #07683b 100%);
  box-shadow: 0 7px 0 #04432a, 0 0 30px rgba(31, 209, 139, .55), inset 0 -6px 14px rgba(0,0,0,.3); text-shadow: 0 2px 0 rgba(0,0,0,.4);
  transition: transform .1s, filter .2s; margin-top: -1.6rem;
}
.btn-spin:hover { filter: brightness(1.08); color: #fff; transform: scale(1.04); }
.btn-spin:active { transform: translateY(5px); box-shadow: 0 2px 0 #04432a; }
.btn-spin.busy { filter: grayscale(.6) brightness(.8); pointer-events: none; }
.btn-spin.free { background: radial-gradient(circle at 50% 30%, #fff3a8, #ffb300 45%, #a35f00 100%); box-shadow: 0 7px 0 #5c3500, 0 0 30px rgba(255, 204, 0, .65); color: #3a1a00; text-shadow: none; }
.spin-label small { display: block; font-family: 'Poppins', sans-serif; font-size: .62rem; font-weight: 800; }
.btn-auto { border: 2px solid rgba(255,255,255,.25); background: rgba(255,255,255,.06); color: #fff; border-radius: 99px; padding: .45rem .9rem; font-weight: 900; font-size: .78rem; cursor: pointer; }
.btn-auto.on { background: var(--pink-grad); border-color: transparent; box-shadow: 0 0 18px rgba(255, 46, 136, .6); }
.sm-status { margin-top: .7rem; min-height: 1.6rem; font-size: .82rem; }
.status-line, .status-idle { display: flex; flex-wrap: wrap; gap: .6rem; align-items: center; justify-content: center; color: rgba(255,255,255,.8); }
.st-win { color: var(--fc-gold); font-weight: 900; }
.st-lose { color: var(--fc-muted); }
.st-fs { color: #1a0933; background: var(--gold-grad); border-radius: 99px; padding: .05rem .6rem; font-weight: 900; }
.st-parts { color: rgba(255,255,255,.65); font-size: .75rem; }

/* bonus overlays */
/* uiOutput() containers are display:contents in current Shiny, so styling
   lives on wrapper divs; the overlay hides itself when no bonus is rendered */
.bonus-layer:not(:has(.bonus-panel)) { display: none; }
.bonus-layer { position: absolute; inset: -.3rem; z-index: 8; display: flex; align-items: center; justify-content: center; background: radial-gradient(circle at 50% 40%, rgba(40, 10, 80, .9), rgba(8, 2, 20, .94)); border-radius: 1.3rem; }
/* no continuous animations underneath an open bonus (keeps repaints cheap) */
.reels-wrap:has(.bonus-panel) .cell.win { animation: none; }
.bonus-panel { text-align: center; padding: 1rem; width: 100%; max-width: 640px; animation: bannerIn .35s ease; }
.bonus-title { font-family: var(--display); font-size: 1.8rem; background: var(--gold-grad); -webkit-background-clip: text; background-clip: text; color: transparent; }
.bonus-sub { color: #eadcff; margin-bottom: .8rem; font-size: .9rem; }
.bonus-status { margin-top: .7rem; color: #ffe8a3; font-weight: 700; font-size: .88rem; }
.bonus-tiles { display: grid; gap: .6rem; margin: 0 auto; }
.bonus-tiles.grid-3 { grid-template-columns: repeat(3, 1fr); max-width: 420px; }
.bonus-tiles.grid-3x3 { grid-template-columns: repeat(3, 1fr); max-width: 380px; }
.bonus-tiles.grid-4x3 { grid-template-columns: repeat(4, 1fr); max-width: 520px; }
.bonus-tile { aspect-ratio: 1.25; border-radius: 1rem; border: 2px solid rgba(255, 204, 0, .5); background: radial-gradient(circle at 50% 30%, #6a2cc0, #2a0b55); cursor: pointer; display: flex; align-items: center; justify-content: center; font-size: 2rem; color: #fff; transition: transform .12s, box-shadow .2s; }
button.bonus-tile:hover { transform: translateY(-3px) scale(1.04); box-shadow: 0 0 24px rgba(255, 204, 0, .6); }
.bonus-tile.revealed { animation: flipIn .4s ease; background: linear-gradient(160deg, #fff3a8, #ffb300); color: #2a1300; font-weight: 900; }
.bonus-tile.revealed .bt-label { font-size: clamp(.75rem, 1.6vw, 1.05rem); }
.bonus-tile.collect, .bonus-tile.trap { background: linear-gradient(160deg, #ff6b81, #b0002a); color: #fff; }
.bonus-tile.mult { background: linear-gradient(160deg, #7df9ff, #00a6c8); }
.bonus-tile.unpicked { opacity: .45; filter: grayscale(.4); animation: none; }
@keyframes flipIn { 0% { transform: rotateY(90deg); } 100% { transform: rotateY(0); } }
.vol-options { display: grid; grid-template-columns: repeat(3, 1fr); gap: .7rem; }
.vol-option { border-radius: 1rem; padding: 1rem .6rem; border: 2px solid rgba(255,204,0,.45); background: linear-gradient(160deg, #8a4a00, #2b1500); color: #fff; cursor: pointer; transition: transform .15s; }
.vol-option:hover { transform: translateY(-4px); box-shadow: 0 0 24px rgba(255,150,0,.6); }
.vol-option.chosen { background: var(--gold-grad); color: #2a1300; }
.vo-tiger { font-size: 1.6rem; }
.vo-label { font-weight: 900; margin-top: .3rem; }
.vo-sub { font-size: .72rem; opacity: .8; }
.bonus-done { margin-top: .9rem; animation: fadeUp .4s ease both; }
.bonus-wheel.done .bonus-done { animation-delay: 4.3s; }
body.turbo .bonus-wheel.done .bonus-done { animation-delay: 2s; }
.bonus-total { font-family: var(--display); font-size: 2rem; color: var(--fc-gold); margin-bottom: .5rem; }
@keyframes fadeUp { 0% { opacity: 0; transform: translateY(10px); } 100% { opacity: 1; transform: none; } }
.top-screen { margin-top: .8rem; border-radius: 1.2rem; min-height: 150px; padding: .8rem; background: linear-gradient(180deg, #3b2410, #1a0f05); border: 2px solid #8a5a22; box-shadow: inset 0 0 30px rgba(0,0,0,.7); }
.top-screen .bonus-panel { max-width: none; }
.top-screen-idle { text-align: center; color: #f0c98a; }
.ts-title { font-family: var(--display); font-size: 1.2rem; }
.ts-sub { font-size: .8rem; opacity: .8; }
.ts-bottles { font-size: 1.6rem; letter-spacing: .3rem; margin-top: .4rem; opacity: .75; }

/* prize wheels */
.prize-wheel { position: relative; display: inline-block; margin: .4rem auto; }
.prize-wheel .wheel-svg { display: block; max-width: 100%; height: auto; filter: drop-shadow(0 10px 30px rgba(0,0,0,.6)); border-radius: 50%; box-shadow: 0 0 0 6px #d4af37, 0 0 0 10px #3b1b00, 0 0 40px rgba(255, 204, 0, .35); }
.wheel-rotor { transform-box: fill-box; transform-origin: 50% 50%; }
.wheel-pointer { position: absolute; top: -14px; left: 50%; transform: translateX(-50%); width: 0; height: 0; border-left: 16px solid transparent; border-right: 16px solid transparent; border-top: 30px solid #ffd23f; z-index: 3; filter: drop-shadow(0 3px 4px rgba(0,0,0,.6)); }
.wheel-hub { position: absolute; top: 50%; left: 50%; transform: translate(-50%, -50%); color: #ffd23f; font-size: 1.6rem; pointer-events: none; }
.prize-wheel.landed .wheel-svg { animation: wheelFlash .9s ease 2; }
@keyframes wheelFlash { 50% { box-shadow: 0 0 0 6px #fff, 0 0 0 10px #ffd23f, 0 0 60px rgba(255, 204, 0, .9); } }

/* ------------------------------------------------------------- table games */
.table-game { max-width: 1180px; margin: 0 auto 3rem; }
.felt {
  border-radius: 220px 220px 1.6rem 1.6rem / 120px 120px 1.6rem 1.6rem; padding: 1.6rem 1.4rem 1.2rem; position: relative; min-height: 360px;
  background: radial-gradient(ellipse at 50% 20%, #1b8a55 0%, #0d5c37 55%, #063a22 100%);
  border: 10px solid #4a2a10; box-shadow: 0 0 0 3px #d4af37, 0 25px 60px rgba(0,0,0,.6), inset 0 0 60px rgba(0,0,0,.5);
}
.bj-empty { text-align: center; padding: 4.5rem 1rem; color: rgba(255,255,255,.75); }
.bj-logo { font-family: var(--display); font-size: 2rem; color: rgba(255, 230, 160, .85); }
.bj-sub { font-size: 1rem; letter-spacing: 3px; text-transform: uppercase; }
.bj-layout { display: flex; flex-direction: column; align-items: center; gap: .8rem; }
.bj-dealer, .bj-hand { display: flex; flex-direction: column; align-items: center; gap: .45rem; }
.hand-label { font-weight: 900; letter-spacing: 3px; font-size: .78rem; color: rgba(255,255,255,.85); display: flex; gap: .5rem; align-items: center; }
.hand-total { background: rgba(0,0,0,.55); border-radius: 99px; padding: .1rem .6rem; font-weight: 900; color: #fff; letter-spacing: 0; font-size: .85rem; }
.cards { display: flex; gap: .45rem; min-height: 122px; }
.bj-hands { display: flex; gap: 1.6rem; flex-wrap: wrap; justify-content: center; margin-top: .6rem; }
.bj-hand { padding: .6rem .8rem; border-radius: 1rem; border: 2px dashed transparent; transition: all .2s; }
.bj-hand.active { border-color: var(--fc-gold); background: rgba(255, 204, 0, .08); box-shadow: 0 0 24px rgba(255,204,0,.25); }
.bj-hand.res-win { background: rgba(31, 209, 139, .15); border-color: var(--fc-green); border-style: solid; }
.bj-hand.res-lose { opacity: .75; }
.bj-hand.res-push { border-color: #8fd3ff; border-style: solid; }
.hand-meta { display: flex; gap: .5rem; align-items: center; flex-wrap: wrap; justify-content: center; }
.hand-bet { font-size: .78rem; color: #ffe8a3; font-weight: 800; }
.hand-result { font-weight: 900; font-size: .8rem; padding: .1rem .6rem; border-radius: 99px; background: #fff; color: #0d5c37; }
.res-lose .hand-result { background: #ff4d6d; color: #fff; }
.shoe-info { font-size: .72rem; color: rgba(255,255,255,.6); }
.side-result { font-weight: 800; color: rgba(255,255,255,.7); }
.side-result.hit { color: var(--fc-gold); text-shadow: 0 0 10px rgba(255,204,0,.7); }
.felt-message { text-align: center; margin-top: 1rem; font-weight: 700; color: #fff; min-height: 1.6rem; display: flex; gap: .6rem; justify-content: center; align-items: center; flex-wrap: wrap; }
.hint-pill { background: rgba(0,0,0,.45); border: 1px solid var(--fc-cyan); color: #9ef7ff; border-radius: 99px; padding: .1rem .7rem; font-size: .78rem; }
.ghost { opacity: .35; display: flex; align-items: center; justify-content: center; font-size: .6rem; text-align: center; color: #fff; border: 2px dashed #fff !important; background: transparent !important; }

.pcard {
  width: 84px; height: 118px; border-radius: 10px; background: linear-gradient(160deg, #ffffff, #f1eadf); position: relative; flex: 0 0 auto;
  box-shadow: 0 6px 14px rgba(0,0,0,.45), inset 0 0 0 1px rgba(0,0,0,.08); font-family: Georgia, 'Times New Roman', serif; user-select: none;
}
.pcard.red { color: #d10f2f; } .pcard.black { color: #14121a; }
.pc-corner { position: absolute; font-weight: 700; font-size: 1.05rem; line-height: 1; text-align: center; }
.pc-corner.tl { top: 6px; left: 7px; } .pc-corner.br { bottom: 6px; right: 7px; transform: rotate(180deg); }
.pc-center { position: absolute; inset: 0; display: flex; align-items: center; justify-content: center; font-size: 2.6rem; }
.pcard.back { background: repeating-linear-gradient(45deg, #7b1b8f 0 8px, #5a0f6b 8px 16px); border: 4px solid #fff; }
.pcard-back-inner { position: absolute; inset: 8px; border: 2px solid rgba(255, 204, 0, .7); border-radius: 6px; }
.pcard.joker { color: #7b2cbf; } .pcard.joker .pc-center { font-size: 3rem; } .pcard.joker .pc-corner { top: 6px; left: 7px; font-size: .8rem; }
.pcard.switched { box-shadow: 0 0 0 3px var(--fc-gold), 0 6px 14px rgba(0,0,0,.45); }
.deal-in { animation: dealIn .42s cubic-bezier(.2, 1.2, .4, 1) both; }
.deal-in.d2 { animation-delay: .12s; } .deal-in.d3 { animation-delay: .24s; } .deal-in.d4 { animation-delay: .36s; } .deal-in.d5 { animation-delay: .48s; } .deal-in.d6 { animation-delay: .6s; }
@keyframes dealIn { 0% { transform: translate(160px, -200px) rotate(25deg); opacity: 0; } 100% { transform: none; opacity: 1; } }
body.turbo .deal-in { animation-duration: .18s; animation-delay: 0s !important; }

.table-controls { margin-top: 1rem; display: flex; flex-direction: column; gap: .7rem; align-items: center; }
.action-row { display: flex; gap: .6rem; flex-wrap: wrap; justify-content: center; align-items: center; min-height: 3rem; }
.bet-row { display: flex; gap: 1rem; align-items: center; flex-wrap: wrap; justify-content: center; }
.bet-chips { display: flex; align-items: center; gap: .45rem; flex-wrap: wrap; }
.bet-info { display: flex; flex-direction: column; align-items: center; }
.bet-amount { font-family: var(--display); color: var(--fc-gold); font-size: 1.2rem; }
.bet-sub { font-size: .7rem; color: var(--fc-muted); }
.chip {
  width: 3.1rem; height: 3.1rem; border-radius: 50%; border: 4px dashed rgba(255,255,255,.85); color: #fff; font-weight: 900; font-size: .72rem; cursor: pointer; position: relative;
  box-shadow: 0 4px 0 rgba(0,0,0,.45), inset 0 0 0 4px rgba(0,0,0,.15); transition: transform .12s; padding: 0;
}
.chip:hover { transform: translateY(-3px) rotate(8deg); }
.chip.selected { transform: translateY(-6px) scale(1.08); box-shadow: 0 0 0 3px var(--fc-gold), 0 0 18px rgba(255,204,0,.8); }
.chip-red { background: #d91e36; } .chip-green { background: #12a150; } .chip-blue { background: #1769d6; }
.chip-orange { background: #f07b11; } .chip-purple { background: #7b2cbf; } .chip-black { background: #1d1d1f; }

/* video poker */
.vp-machine { border-radius: 1.6rem; padding: 1rem; background: linear-gradient(180deg, #0d2f6b, #061330); border: 3px solid #d4af37; box-shadow: 0 0 40px rgba(0, 120, 255, .25), 0 25px 60px rgba(0,0,0,.6); }
.vp-paytable { width: 100%; border-collapse: separate; border-spacing: 0; font-size: .82rem; background: #000a3a; border-radius: .8rem; overflow: hidden; border: 2px solid #ffd23f; }
.vp-paytable th, .vp-paytable td { padding: .22rem .6rem; text-align: right; color: #ffd23f; font-weight: 800; }
.vp-paytable th:first-child, .vp-paytable td:first-child { text-align: left; color: #ffe98a; }
.vp-paytable thead th { background: #001466; color: #fff; }
.vp-paytable .col-active { background: rgba(255, 46, 136, .45); color: #fff; }
.vp-paytable tr.row-hit td { background: #ffd23f; color: #061330; animation: rowFlash .8s ease 3; }
@keyframes rowFlash { 50% { background: #fff; } }
.vp-screen { margin: 1rem 0; }
.vp-cards { display: flex; justify-content: center; gap: .8rem; flex-wrap: wrap; }
.vp-cards .pcard { width: 112px; height: 156px; }
.vp-cards .pc-center { font-size: 3.3rem; }
.pcard.clickable { cursor: pointer; transition: transform .12s; }
.pcard.clickable:hover { transform: translateY(-6px); }
.pcard.held { transform: translateY(-10px); box-shadow: 0 0 0 4px var(--fc-gold), 0 10px 24px rgba(255, 204, 0, .4); }
.held-tag { position: absolute; bottom: -1.6rem; left: 50%; transform: translateX(-50%); background: var(--gold-grad); color: #2a1300; font-family: var(--display); font-size: .8rem; padding: .05rem .7rem; border-radius: 99px; }
.vp-message { text-align: center; margin-top: 2rem; font-weight: 800; min-height: 1.5rem; }
.vp-win { color: var(--fc-gold); font-size: 1.15rem; text-shadow: 0 0 14px rgba(255, 204, 0, .7); }
.vp-controls { display: grid; grid-template-columns: minmax(370px, 2.3fr) 1.3fr 1fr 1fr 1fr; gap: .7rem; align-items: stretch; }
.vp-controls .bet-amount { display: flex; flex-direction: column; align-items: center; line-height: 1.15; }
.vp-bet-formula { font-family: 'Poppins', sans-serif; font-size: .72rem; color: var(--fc-muted); font-weight: 700; white-space: nowrap; }
.vp-controls .ctl-group { justify-content: center; }
.vp-coin-btns { display: flex; gap: .4rem; }

/* roulette */
.rl-layout { display: grid; grid-template-columns: minmax(260px, 360px) 1fr; gap: 1.2rem; align-items: start; }
.rl-wheel-area { display: flex; flex-direction: column; align-items: center; gap: .8rem; background: var(--fc-panel); border-radius: 1.4rem; padding: 1rem; border: 1px solid rgba(255,255,255,.1); }
.rl-wheels { display: grid; gap: .6rem; justify-items: center; }
.rl-wheels.n2 { grid-template-columns: repeat(2, 1fr); }
.rl-wheels.n3, .rl-wheels.n4 { grid-template-columns: repeat(2, 1fr); }
.rl-wheels.n5, .rl-wheels.n6 { grid-template-columns: repeat(2, 1fr); }
.rl-wheel { position: relative; }
.rl-wheel svg { display: block; filter: drop-shadow(0 12px 24px rgba(0,0,0,.6)); }
.rl-rotor { transform-box: fill-box; transform-origin: 50% 50%; }
.rl-ball-track { position: absolute; inset: 0; pointer-events: none; }
.rl-ball { position: absolute; top: 12%; left: 50%; width: 7%; height: 7%; min-width: 8px; min-height: 8px; transform: translateX(-50%); border-radius: 50%; background: radial-gradient(circle at 35% 30%, #fff, #c9c9c9 60%, #777); box-shadow: 0 2px 4px rgba(0,0,0,.6); }
.rl-wheel::before { content: ""; position: absolute; top: -6px; left: 50%; transform: translateX(-50%); border-left: 9px solid transparent; border-right: 9px solid transparent; border-top: 16px solid #ffd23f; z-index: 3; }
.rl-result-bubble { position: absolute; top: 50%; left: 50%; transform: translate(-50%, -50%) scale(0); width: 30%; height: 30%; border-radius: 50%; display: flex; align-items: center; justify-content: center; font-family: var(--display); font-size: 1.3rem; color: #fff; border: 3px solid #ffd23f; transition: transform .3s cubic-bezier(.3, 1.6, .5, 1); }
.rl-result-bubble.show { transform: translate(-50%, -50%) scale(1); }
.rl-result-bubble.red { background: #c0142b; } .rl-result-bubble.black { background: #15121c; } .rl-result-bubble.green { background: #0d8a3e; }
.rl-last { width: 100%; min-height: 4rem; text-align: center; }
.rl-last-empty { color: var(--fc-muted); }
.rl-last-nums { display: flex; gap: .4rem; justify-content: center; flex-wrap: wrap; }
.rl-ball-num, .rl-hist { display: inline-flex; align-items: center; justify-content: center; border-radius: 50%; font-weight: 900; color: #fff; }
.rl-ball-num { width: 2.6rem; height: 2.6rem; font-size: 1.05rem; border: 2px solid #ffd23f; animation: bannerIn .35s ease; }
.rl-ball-num.red, .rl-hist.red { background: #c0142b; } .rl-ball-num.black, .rl-hist.black { background: #1f1b27; } .rl-ball-num.green, .rl-hist.green { background: #0d8a3e; }
.rl-net { margin-top: .5rem; font-weight: 800; } .rl-net.up { color: var(--fc-green); } .rl-net.down { color: var(--fc-red); }
.rl-net span { font-weight: 600; font-size: .82rem; }
.rl-win-lines { font-size: .78rem; color: #eadcff; margin-top: .3rem; max-height: 140px; overflow: auto; }
.rl-win-lines div { display: flex; justify-content: space-between; gap: .6rem; border-bottom: 1px solid rgba(255,255,255,.06); padding: .1rem 0; }
.rl-win-lines span { color: var(--fc-gold); font-weight: 800; }
.rl-history { display: flex; flex-wrap: wrap; gap: .25rem; justify-content: center; }
.rl-hist { width: 1.7rem; height: 1.7rem; font-size: .7rem; }
.rl-board { background: radial-gradient(ellipse at 50% 20%, #1b8a55 0%, #0d5c37 60%, #063a22 100%); border-radius: 1.4rem; padding: 1rem; border: 8px solid #4a2a10; box-shadow: 0 0 0 3px #d4af37, 0 25px 60px rgba(0,0,0,.6); }
.rl-table { display: grid; grid-template-columns: 1fr 12fr 1fr; grid-template-rows: 3fr 1fr 1fr; gap: 0; user-select: none; }
.rl-zero { grid-column: 1; grid-row: 1; display: flex; flex-direction: column; position: relative; }
.rl-zero .rl-num { flex: 1; border-radius: 50% 0 0 50% / 30% 0 0 30%; }
.rl-zero.double .rl-num:first-child { border-radius: 50% 0 0 0 / 30% 0 0 0; } .rl-zero.double .rl-num:nth-child(2) { border-radius: 0 0 0 50% / 0 0 0 30%; }
.rl-grid { grid-column: 2; grid-row: 1; display: grid; grid-template-columns: repeat(12, 1fr); grid-template-rows: repeat(3, 1fr); position: relative; }
.rl-num, .rl-out { position: relative; display: flex; align-items: center; justify-content: center; border: 1.5px solid rgba(255,255,255,.75); color: #fff; font-weight: 800; cursor: pointer; min-height: 3rem; transition: background .15s, box-shadow .15s; font-size: .95rem; }
.rl-num span { pointer-events: none; }
.rl-num.red { background: #b3122a; } .rl-num.black { background: #17141d; } .rl-num.green { background: #0b7a37; }
.rl-num:hover, .rl-out:hover { box-shadow: inset 0 0 0 3px #ffd23f; filter: brightness(1.2); }
.rl-cols { grid-column: 3; grid-row: 1; display: grid; grid-template-rows: repeat(3, 1fr); }
.rl-dozens { grid-column: 2; grid-row: 2; display: grid; grid-template-columns: repeat(3, 1fr); }
.rl-outside { grid-column: 2; grid-row: 3; display: grid; grid-template-columns: repeat(6, 1fr); }
.rl-out { background: transparent; font-size: .85rem; min-height: 2.6rem; }
.rl-out.red span { color: #ff3048; font-size: 1.5rem; } .rl-out.black span { color: #000; font-size: 1.5rem; -webkit-text-stroke: 1px #fff; }
.rl-spot { position: absolute; width: 18px; height: 18px; margin: -9px 0 0 -9px; border-radius: 50%; z-index: 4; cursor: pointer; background: rgba(255, 255, 255, 0); transition: background .12s, transform .12s; }
.rl-spot:hover { background: rgba(255, 210, 63, .85); transform: scale(1.25); box-shadow: 0 0 10px #ffd23f; }
.rl-spot.split-zero { width: 22px; height: 22px; margin: -11px 0 0 -11px; }
.rl-chip { position: absolute; top: 50%; left: 50%; transform: translate(-50%, -50%); min-width: 1.9rem; height: 1.9rem; padding: 0 .2rem; border-radius: 50%; display: flex; align-items: center; justify-content: center; font-size: .58rem; font-weight: 900; color: #fff; border: 3px dashed rgba(255,255,255,.9); box-shadow: 0 3px 6px rgba(0,0,0,.6); z-index: 5; pointer-events: none; animation: chipIn .25s cubic-bezier(.3, 1.6, .5, 1); }
.rl-spot .rl-chip { min-width: 1.6rem; height: 1.6rem; font-size: .5rem; }
@keyframes chipIn { 0% { transform: translate(-50%, -80%) scale(.4); opacity: 0; } 100% { transform: translate(-50%, -50%) scale(1); opacity: 1; } }
.call-bets { display: flex; gap: .5rem; flex-wrap: wrap; align-items: center; justify-content: center; margin-top: .8rem; }
.btn-call { background: rgba(0,0,0,.45); color: #ffe8a3; border: 1px solid #d4af37; padding: .35rem .8rem; font-size: .78rem; }
.btn-call span { display: block; font-size: .62rem; color: #c9b37a; font-weight: 600; }
.btn-call:hover { background: #d4af37; color: #1a0f00; }
.multi-ctl { display: flex; align-items: center; gap: .5rem; }
.multi-ctl .shiny-options-group { display: flex; gap: .3rem; }
.multi-ctl .form-check-label, .multi-ctl label > span { padding: .25rem .65rem; }

/* -------------------------------------------------------------- meta pages */
.meta-page { max-width: 1200px; margin: 0 auto 3rem; }
.album-actions { display: flex; align-items: center; gap: .8rem; flex-wrap: wrap; }
.album-bar { width: 220px; height: 20px; }
.album-hint { background: var(--fc-panel); border-radius: 1rem; padding: .8rem 1rem; color: #dccbff; font-size: .88rem; margin-bottom: 1rem; border: 1px dashed rgba(255,255,255,.2); }
.recent-pulls { display: flex; align-items: center; gap: .4rem; flex-wrap: wrap; margin-bottom: 1rem; }
.mini-card { font-size: 1.5rem; width: 2.4rem; height: 3rem; display: inline-flex; align-items: center; justify-content: center; background: linear-gradient(160deg, #3b1670, #1d0838); border-radius: .4rem; border: 1px solid rgba(255,255,255,.2); }
.mini-card.lucky { border-color: var(--fc-gold); box-shadow: 0 0 10px rgba(255,204,0,.6); }
.album-sets { display: grid; grid-template-columns: repeat(auto-fill, minmax(480px, 1fr)); gap: 1rem; }
.album-set { background: var(--fc-panel); border-radius: 1.2rem; padding: .9rem; border: 1px solid rgba(255,255,255,.1); }
.album-set.complete { border-color: var(--fc-green); box-shadow: 0 0 22px rgba(31, 209, 139, .25); }
.set-head { display: flex; align-items: center; gap: .6rem; margin-bottom: .6rem; }
.set-icon { font-size: 1.8rem; }
.set-name { font-family: var(--display); font-size: .95rem; flex: 1; }
.set-count { margin-left: .5rem; font-family: 'Poppins', sans-serif; color: var(--fc-muted); font-size: .78rem; }
.set-reward { font-weight: 800; color: var(--fc-gold); font-size: .85rem; }
.set-cards { display: grid; grid-template-columns: repeat(9, minmax(0, 1fr)); gap: .35rem; }
.album-card { position: relative; min-width: 0; aspect-ratio: .72; border-radius: .45rem; background: linear-gradient(160deg, #4a1d86, #1c0838); border: 1px solid rgba(255,255,255,.18); display: flex; flex-direction: column; align-items: center; justify-content: center; padding: .15rem; text-align: center; }
.album-card.missing { background: rgba(255,255,255,.04); border-style: dashed; }
.album-card.missing .ac-glyph { color: rgba(255,255,255,.25); font-family: var(--display); font-size: 1rem; }
.album-card.lucky.owned { border: 2px solid var(--fc-gold); box-shadow: 0 0 10px rgba(255,204,0,.55); background: linear-gradient(160deg, #7a5a00, #2b1a00); }
.album-card.lucky.missing { border-color: rgba(255, 204, 0, .5); }
.album-card.s5.owned { background: linear-gradient(160deg, #b3127a, #3b0a5e); }
.album-card.s4.owned { background: linear-gradient(160deg, #1565c0, #1c0838); }
.ac-glyph { font-size: clamp(1rem, 2.3vw, 1.45rem); }
.ac-name { font-size: .5rem; line-height: 1.05; color: #eadcff; margin-top: .1rem; max-width: 100%; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.ac-stars { font-size: .42rem; color: var(--fc-gold); letter-spacing: -1px; }
.ac-count { position: absolute; top: -6px; right: -6px; background: var(--pink-grad); color: #fff; font-size: .55rem; font-weight: 900; border-radius: 99px; padding: 0 .3rem; }

.modal-content:has(.lucky-board) { background: radial-gradient(circle at 50% 0%, #7a5a00, #1d0838 70%); border: 3px solid var(--fc-gold); border-radius: 1.6rem; color: #fff; }
.lucky-board { text-align: center; padding: .5rem; }
.lucky-title { font-family: var(--display); font-size: 1.8rem; background: var(--gold-grad); -webkit-background-clip: text; background-clip: text; color: transparent; }
.lucky-sub { color: #f6e6ff; margin-bottom: 1rem; }
.lucky-cards { display: flex; justify-content: center; gap: .9rem; margin-bottom: 1rem; }
.lucky-card { width: 130px; height: 180px; border-radius: 1rem; border: 3px solid var(--fc-gold); background: repeating-linear-gradient(45deg, #1b7a3a 0 10px, #14602d 10px 20px); font-size: 2.8rem; cursor: pointer; display: flex; align-items: center; justify-content: center; color: #fff; transition: transform .15s; }
button.lucky-card:hover { transform: translateY(-6px) rotate(-2deg); box-shadow: 0 0 30px rgba(255, 204, 0, .6); }
.lucky-card.flipped { background: linear-gradient(160deg, #fff3a8, #ffb300); color: #2a1300; font-size: .95rem; font-weight: 900; padding: .6rem; animation: flipIn .45s ease; opacity: .55; }
.lucky-card.flipped.chosen { opacity: 1; transform: scale(1.08); box-shadow: 0 0 30px rgba(255, 204, 0, .8); }

.wheels-row { display: grid; grid-template-columns: repeat(auto-fit, minmax(340px, 1fr)); gap: 1.2rem; }
.wheel-card { text-align: center; background: var(--fc-panel); border-radius: 1.5rem; padding: 1.2rem; border: 1px solid rgba(255,255,255,.1); }
.wheel-card.daily { background: radial-gradient(circle at 50% 0%, rgba(255, 204, 0, .22), transparent 60%), var(--fc-panel); border-color: rgba(255,204,0,.4); }
.wc-title { font-family: var(--display); color: #ffe8a3; margin-bottom: .4rem; }
.wheel-won { animation: wonIn .45s ease both; }
@keyframes wonIn { from { opacity: 0; transform: translateY(6px); } to { opacity: 1; transform: none; } }
.wheel-wait { display: flex; flex-direction: column; gap: .1rem; margin-top: .6rem; color: var(--fc-muted); }
.wheel-wait strong { font-family: var(--display); font-size: 1.5rem; color: #fff; font-weight: 400; }
.wheel-won { color: var(--fc-gold); font-weight: 800; }
.mult-ring { display: flex; justify-content: center; gap: .4rem; margin: .4rem 0 .8rem; }
.mult-chip { border: 1px solid rgba(255,204,0,.5); border-radius: 99px; padding: .1rem .6rem; font-weight: 900; color: #ffe8a3; }
.mult-chip.hit { background: var(--gold-grad); color: #2a1300; animation: bannerIn .4s ease 4.3s both; }

.star-balance { display: flex; align-items: center; gap: .8rem; }
.sb-stars { font-family: var(--display); font-size: 1.5rem; color: var(--fc-gold); }
.market-section { margin: 1rem 0 .6rem; font-size: 1.05rem; color: #fff; }
.market-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(180px, 1fr)); gap: .8rem; }
.market-item { background: var(--fc-panel); border-radius: 1.1rem; padding: 1rem .8rem; text-align: center; border: 1px solid rgba(255,255,255,.1); display: flex; flex-direction: column; gap: .25rem; align-items: center; transition: transform .15s; }
.market-item:hover { transform: translateY(-3px); border-color: rgba(255,204,0,.5); }
.market-item.owned { border-color: var(--fc-green); }
.market-item.active { box-shadow: 0 0 20px rgba(31, 209, 139, .45); }
.mi-icon { font-size: 2.4rem; }
.mi-name { font-weight: 800; }
.mi-desc { font-size: .75rem; color: var(--fc-muted); min-height: 2.2em; }
.btn-buy { background: var(--gold-grad); color: #2a1300; padding: .35rem 1rem; font-size: .8rem; margin-top: .3rem; box-shadow: 0 3px 0 #a35f00; }
.market-item.owned .btn-buy { background: linear-gradient(180deg, #2df5a3, #10a36a); box-shadow: 0 3px 0 #06613e; }
.boost-strip { display: flex; gap: .5rem; flex-wrap: wrap; }
