.mon-task { font-size: .68rem; color: var(--fc-muted); min-height: 2.4em; margin-bottom: .3rem; }

.vip-hero { display: grid; grid-template-columns: auto 1fr auto; gap: 1.2rem; align-items: center; border-radius: 1.4rem; padding: 1.2rem 1.4rem; background: radial-gradient(circle at 0% 50%, color-mix(in srgb, var(--tier) 40%, transparent), transparent 60%), var(--fc-panel-2); border: 2px solid var(--tier); box-shadow: 0 0 30px color-mix(in srgb, var(--tier) 40%, transparent); margin-bottom: 1rem; }
