.pf-feed { grid-column: 1 / 5; font-size: .8rem; }
.pf-feed ul { margin: .3rem 0 0; padding-left: 1rem; color: #dccbff; }
.pf-reset { grid-column: 5 / 7; display: flex; align-items: flex-end; justify-content: flex-end; gap: .8rem; flex-wrap: wrap; }
.pf-id { font-size: .7rem; color: var(--fc-muted); text-align: right; }
