/* ------------------------------------------------------- toasts & overlays */
#fc-toasts { position: fixed; top: 76px; right: 16px; z-index: 2000; display: flex; flex-direction: column; gap: .5rem; width: min(360px, 92vw); pointer-events: none; }
.fc-toast { pointer-events: auto; display: flex; gap: .7rem; align-items: center; padding: .7rem .9rem; border-radius: 1rem; background: rgba(29, 8, 56, .96); border: 1px solid rgba(255,255,255,.14); border-left: 5px solid var(--fc-cyan); box-shadow: 0 14px 30px rgba(0,0,0,.55); animation: toastIn .35s cubic-bezier(.3, 1.4, .5, 1); cursor: pointer; }
.fc-toast.success { border-left-color: var(--fc-green); } .fc-toast.warning { border-left-color: var(--fc-gold); }
.fc-toast.pack { border-left-color: var(--fc-pink); } .fc-toast.monster { border-left-color: #b06bff; }
.fc-toast.out { animation: toastOut .4s ease forwards; }
.ht-icon { font-size: 1.6rem; }
.ht-title { font-weight: 800; font-size: .9rem; }
.ht-text { font-size: .8rem; color: #dccbff; }
@keyframes toastIn { from { transform: translateX(120%); opacity: 0; } to { transform: none; opacity: 1; } }
@keyframes toastOut { to { transform: translateX(120%); opacity: 0; } }

#fc-celebrate { position: fixed; inset: 0; z-index: 3000; display: none; align-items: center; justify-content: center; background: radial-gradient(circle, rgba(40, 6, 70, .75), rgba(0,0,0,.88)); cursor: pointer; overflow: hidden; }
#fc-celebrate.show { display: flex; animation: fadeIn .25s ease; }
@keyframes fadeIn { from { opacity: 0; } to { opacity: 1; } }
.celebrate-inner { text-align: center; position: relative; animation: bannerIn .5s cubic-bezier(.3, 1.6, .5, 1); }
.cb-burst { will-change: transform; position: absolute; top: 50%; left: 50%; width: 900px; height: 900px; margin: -450px 0 0 -450px; background: repeating-conic-gradient(rgba(255, 204, 0, .16) 0 10deg, transparent 10deg 20deg); border-radius: 50%; animation: spinBurst 12s linear infinite; z-index: -1; mask-image: radial-gradient(circle, #000 20%, transparent 65%); }
@keyframes spinBurst { to { transform: rotate(360deg); } }
.cb-icon { font-size: 5rem; animation: floaty 2s ease-in-out infinite; will-change: transform; }
.cb-title { font-family: var(--display); font-size: clamp(2.6rem, 8vw, 5.5rem); background: var(--gold-grad); -webkit-background-clip: text; background-clip: text; color: transparent; filter: drop-shadow(0 6px 0 #7a3b00) drop-shadow(0 0 30px rgba(255, 170, 0, .6)); line-height: 1.05; }
.celebrate-inner.mega .cb-title, .celebrate-inner.epic .cb-title { background: linear-gradient(180deg, #fff, #ff9ad5 40%, #ff2e88); -webkit-background-clip: text; background-clip: text; filter: drop-shadow(0 6px 0 #6a0040) drop-shadow(0 0 36px rgba(255, 46, 136, .8)); }
.celebrate-inner.level .cb-title, .celebrate-inner.vip .cb-title { background: linear-gradient(180deg, #fff, #9ef7ff 40%, #00c2ff); -webkit-background-clip: text; background-clip: text; filter: drop-shadow(0 6px 0 #00445a) drop-shadow(0 0 30px rgba(0, 194, 255, .7)); }
.cb-amount { font-family: var(--display); font-size: clamp(2rem, 6vw, 4rem); color: #fff; text-shadow: 0 4px 0 rgba(0,0,0,.5); font-variant-numeric: tabular-nums; }
.cb-sub { color: #f6e6ff; font-weight: 700; margin-top: .3rem; }
.cb-tap { margin-top: 1.2rem; font-size: .7rem; letter-spacing: 3px; color: rgba(255,255,255,.5); text-transform: uppercase; }
.coin-drop { position: fixed; top: -60px; font-size: 2.2rem; animation-name: coinFall; animation-timing-function: linear; animation-iteration-count: infinite; pointer-events: none; }
@keyframes coinFall { 0% { transform: translateY(0) rotate(0); } 100% { transform: translateY(115vh) rotate(540deg); } }

/* ------------------------------------------------------- multi-hand video poker */
.vp-hands-btns { display: flex; gap: .3rem; justify-content: center; }
.vp-hands-btn { min-width: 2.3rem; height: 2.3rem; border-radius: 50%; border: 2px solid rgba(255, 210, 63, .55); background: #071a45; color: #ffd23f; font-weight: 900; font-size: .85rem; cursor: pointer; transition: transform .1s, background .15s; }
