.vp-mini-hand.lost { opacity: .55; }
.mh-no { font-size: .62rem; color: #8fa4d8; width: 1.1rem; text-align: right; font-weight: 800; }
.mh-cards { display: flex; gap: 2px; }
.mh-res { font-size: .62rem; color: #ffd23f; font-weight: 800; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; flex: 1; text-align: right; }
.mcard { display: inline-flex; align-items: center; justify-content: center; width: 1.55rem; height: 1.85rem; border-radius: 3px; background: #fff; font-size: .68rem; font-weight: 900; letter-spacing: -.5px; line-height: 1; }
