@keyframes mcIn { from { transform: rotateY(90deg); } to { transform: none; } }
.vp-double { display: flex; justify-content: center; align-items: flex-end; gap: 2rem; flex-wrap: wrap; }
.vp-dbl-dealer, .vp-dbl-picks { display: flex; flex-direction: column; align-items: center; gap: .5rem; }
