.vp-dbl-dealer .pc-center { font-size: 3.3rem; }
.vp-dbl-slot { cursor: pointer; transition: transform .12s; }
.vp-dbl-slot:hover { transform: translateY(-8px) rotate(-1deg); }
.vp-dbl-slot .pcard { box-shadow: 0 0 0 3px rgba(255, 210, 63, .6); }
.pcard.chosen.win { box-shadow: 0 0 0 4px var(--fc-green), 0 0 28px rgba(31, 209, 139, .7); transform: translateY(-10px); }
.pcard.chosen.lose { box-shadow: 0 0 0 4px var(--fc-red), 0 0 28px rgba(255, 77, 109, .6); transform: translateY(-10px); }
.pcard.chosen.push { box-shadow: 0 0 0 4px var(--fc-cyan), 0 0 28px rgba(0, 194, 255, .6); transform: translateY(-10px); }
.pcard.dim { opacity: .45; filter: grayscale(.4); }
.vp-double-bar { display: flex; justify-content: center; align-items: center; gap: .7rem; margin-top: .7rem; flex-wrap: wrap; animation: fadeUp .3s ease; }
