@keyframes pulseGold { 0%, 100% { box-shadow: 0 5px 0 #a35f00, 0 0 0 rgba(255, 204, 0, 0); } 50% { box-shadow: 0 5px 0 #a35f00, 0 0 26px rgba(255, 204, 0, .75); } }
