@keyframes shake { 25% { transform: translateX(-5px); } 75% { transform: translateX(5px); } }

/* ---------------------------------------------------------------- My Stats */
.stats-page .pos { color: var(--fc-green); } .stats-page .neg { color: var(--fc-red); } .stats-page .flat { color: var(--fc-muted); }
