.lg-bal::before { background: var(--fc-green); } .lg-peak::before { background: var(--fc-gold); } .lg-dd::before { background: rgba(255, 77, 109, .55); height: 10px !important; }
.stats-chart-wrap { position: relative; }
.stats-chart { width: 100%; height: auto; display: block; }
.stats-chart .sc-grid { stroke: rgba(255, 255, 255, .07); stroke-width: 1; }
