.stats-table tr.current td { background: rgba(255, 204, 0, .1); }
.you-tag { margin-left: .4rem; font-size: .6rem; font-weight: 900; background: var(--pink-grad); color: #fff; border-radius: 99px; padding: .05rem .45rem; vertical-align: middle; text-transform: uppercase; letter-spacing: .5px; }
