.cat-hero { margin-bottom: .8rem; }
.cat-fav { font-family: var(--display); font-size: 1.25rem; background: var(--gold-grad); -webkit-background-clip: text; background-clip: text; color: transparent; }
.cat-tags { display: flex; gap: .35rem; flex-wrap: wrap; margin-top: .3rem; }
.cat-tag { font-size: .72rem; font-weight: 700; border: 1px solid rgba(255, 255, 255, .2); border-radius: 99px; padding: .1rem .55rem; color: #e6d8ff; }
.cat-tag.gold { border-color: var(--fc-gold); color: var(--fc-gold); }
.category .family-row { grid-template-columns: 170px 1fr; }
.arch-hero { display: flex; gap: .9rem; align-items: center; margin-bottom: .7rem; }
.arch-icon { font-size: 3rem; line-height: 1; filter: drop-shadow(0 0 12px rgba(255, 204, 0, .45)); animation: popIn .5s ease; }
@keyframes popIn { from { transform: scale(.4); opacity: 0; } 70% { transform: scale(1.12); } to { transform: none; opacity: 1; } }
.arch-name { font-family: var(--display); font-size: 1.35rem; color: #ffe8a3; }
.arch-conf { color: var(--fc-cyan); font-size: .75rem; font-weight: 700; }
.arch-desc { color: #e6d8ff; font-size: .85rem; margin-top: .15rem; }
.feat-table td:nth-child(2) { text-align: right; font-weight: 800; }
.arch-votes { display: flex; gap: .35rem; flex-wrap: wrap; margin-top: .6rem; }
.vote { font-size: .72rem; border-radius: 99px; padding: .1rem .55rem; background: rgba(255, 255, 255, .08); }
.vote.top { background: var(--gold-grad); color: #2a1300; font-weight: 800; }

/* ------------------------------------------------------------- responsive */
@media (max-width: 1400px) {
  .navbar .nav-link { font-size: .72rem; padding: .35rem .45rem !important; }
  .hud-vip, .hud-stars { display: none; }
}
@media (max-width: 1100px) {
  .vp-controls { grid-template-columns: 1fr 1fr 1fr; }
  .vp-hands-grid.n25, .vp-hands-grid.n5 { grid-template-columns: repeat(3, minmax(150px, 1fr)); }
  .cat-row { grid-template-columns: repeat(3, 1fr); }
  .rl-layout { grid-template-columns: 1fr; }
  .profile-grid { grid-template-columns: repeat(3, 1fr); }
  .pf-feed, .pf-reset { grid-column: 1 / -1; }
}
@media (max-width: 800px) {
  .sm-controls { grid-template-columns: 1fr; }
  .btn-spin { margin-top: 0; }
  .monsters { grid-template-columns: repeat(2, 1fr); }
  .dash-grid, .rewards-grid { grid-template-columns: 1fr; }
  .vp-controls { grid-template-columns: 1fr 1fr; }
  .stats-grid { grid-template-columns: 1fr; }
  .vp-hands-grid, .vp-hands-grid.n3, .vp-hands-grid.n5, .vp-hands-grid.n10, .vp-hands-grid.n25 { grid-template-columns: repeat(auto-fill, minmax(150px, 1fr)); }
  .jb-pots { grid-template-columns: repeat(2, 1fr); }
  .hero { flex-direction: column; text-align: center; }
  .set-cards { grid-template-columns: repeat(5, minmax(0, 1fr)); }
  .album-sets { grid-template-columns: 1fr; }
  .pcard { width: 64px; height: 90px; } .pc-center { font-size: 2rem; }
  .vp-cards .pcard { width: 64px; height: 90px; }
}

