      else if (m.fs_ended) banner(machine, esc(t('FREE SPINS WON')) + ' <b>' + fmt(m.fs_won) + '</b>', 'fs', 2200);
      else if (m.win > 0 && (m.tier === 'win')) banner(machine, esc(t('WIN')) + ' <b>' + fmt(m.win) + '</b>', 'small', 1300);
      if (m.tier === 'big' || m.tier === 'mega' || m.tier === 'epic') {
